import * as T from './vendor/three.module.min.js';
export function createFinale(parent){
const el=document.createElement('section');el.className='journey-finale';el.innerHTML=`<div class="finale-copy"><p class="eyebrow">10 / THE FOUNDATIONS</p><h2>Always a student.<br><em>Still becoming.</em></h2><div class="education-pair"><article><small>GRADE 10</small><h3>Kadambari Academy</h3><strong>3.84</strong><span>GPA</span></article><article><small>GRADE 12</small><h3>St. Xavier’s College</h3><strong>3.86</strong><span>GPA</span></article></div></div><div class="contact-copy"><p class="eyebrow">11 / THE NEXT POSSIBILITY</p><h2>What shall we<br><em>build next?</em></h2><p>Prasiddha Mainali · Kathmandu, Nepal</p><a class="contact-email" href="mailto:prasiddha.mainali2@gmail.com">prasiddha.mainali2@gmail.com ↗</a><nav aria-label="Contact links"><a href="https://www.linkedin.com/in/prasiddha-mainali-105bb0352/" target="_blank" rel="noopener">LinkedIn ↗</a><a href="https://github.com/DeV-PrasiddhA" target="_blank" rel="noopener">GitHub ↗</a></nav><button class="replay-world">Back to where it began ↻</button><small>Every ending is another beginning.</small></div><div class="finale-iris"></div>`;parent.append(el);
const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};let t=0,paused=false,clock=0,last=0,looping=false;
function restart(){if(looping)return;looping=true;el.classList.add('loop-closing');setTimeout(()=>{window.scrollTo({top:0,behavior:'instant'});window.cinematicY=0;history.replaceState(null,'',location.pathname);setTimeout(()=>{el.classList.remove('loop-closing');looping=false;},350);},650)}el.querySelector('button').onclick=restart;
addEventListener('wheel',e=>{if(t>61.8&&scrollY+innerHeight>=document.documentElement.scrollHeight-8&&e.deltaY>12)restart()},{passive:true});
let renderer;try{renderer=new T.WebGLRenderer({alpha:true,antialias:true});}catch{}
if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));el.prepend(renderer.domElement);const scene=new T.Scene(),camera=new T.PerspectiveCamera(58,innerWidth/innerHeight,.1,160);scene.fog=new T.FogExp2(0x040e18,.025);scene.add(new T.HemisphereLight(0xaadfff,0x33200e,3));const group=new T.Group();scene.add(group);const rings=[];for(let i=0;i<32;i++){const r=new T.Mesh(new T.TorusGeometry(6.4,.035,8,96),new T.MeshBasicMaterial({color:i%3?0x4d9eac:0xe9c184,transparent:true,opacity:.65}));r.position.z=-i*5;r.rotation.z=i*.12;group.add(r);rings.push(r)}const p=new Float32Array(1200);for(let i=0;i<400;i++){p[i*3]=Math.cos(i*2.4)*(3+i%8);p[i*3+1]=Math.sin(i*2.4)*(3+i%8);p[i*3+2]=-i%150}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(p,3));const stars=new T.Points(geo,new T.PointsMaterial({color:0xf4d698,size:.065}));group.add(stars);const core=new T.Mesh(new T.IcosahedronGeometry(2.1,2),new T.MeshStandardMaterial({color:0xe5be7b,wireframe:true,metalness:.6,roughness:.25}));scene.add(core);function size(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}size();addEventListener('resize',size);function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-last)/1000);last=now;if(t<52||document.hidden)return;if(!paused)clock+=dt;const travel=ease((t-52)/10);camera.position.set(Math.sin(travel*Math.PI)*1.4,.15,8-travel*35);camera.lookAt(0,0,camera.position.z-20);group.rotation.z=paused?0:clock*.035;core.position.set(innerWidth<760?0:4,innerWidth<760?2:0,camera.position.z-13);core.rotation.set(clock*.13,clock*.2,travel*2);core.scale.setScalar(.8+ease((t-57)/3)*.5);rings.forEach((r,i)=>r.rotation.y=Math.sin(clock*.35+i*.25)*.12);renderer.render(scene,camera)}requestAnimationFrame(frame)}
return {update(value,stop){t=value;paused=stop;el.style.visibility=t>52?'visible':'hidden';el.style.opacity=ease((t-52)/1.1);el.inert=t<52;const c=ease((t-57)/1.5),a=el.querySelector('.finale-copy'),b=el.querySelector('.contact-copy');a.style.opacity=1-c;a.style.transform=`perspective(1000px) translateZ(${-c*500}px) rotateY(${-c*20}deg)`;a.inert=c>.5;b.style.opacity=c;b.style.transform=`translateY(${(1-c)*45}px)`;b.inert=c<.8;}};
}
